// Neumorphic container
const NeumorphicContainer = ({ children, style }: any) => (
  <View style={[styles.neumorphicOuter, style]}>
    <View style={styles.neumorphicInner}>{children}</View>
  </View>
);

// Neumorphic button with touch effect
function NeumorphicButton({ children, onPress, style }: any) {
  const scale = React.useRef(new Animated.Value(1)).current;

  const handlePressIn = () => {
    Animated.spring(scale, {
      toValue: 0.97,
      useNativeDriver: true,
      speed: 50,
      bounciness: 0,
    }).start();
  };

  const handlePressOut = () => {
    Animated.spring(scale, {
      toValue: 1,
      useNativeDriver: true,
      speed: 50,
      bounciness: 8,
    }).start();
  };

  return (
    <TouchableOpacity
      activeOpacity={0.85}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      onPress={onPress}
      style={{ width: '100%' }}
    >
      <Animated.View
        style={[
          {
            transform: [{ scale }],
          },
          styles.neumorphicOuter,
          style,
        ]}
      >
        <View style={styles.neumorphicInner}>{children}</View>
      </Animated.View>
    </TouchableOpacity>
  );
}

export default function RepertoiresScreen(): JSX.Element {
  const navigation = useNavigation<NavigationProp>();
  const [repertorios, setRepertorios] = useState<any[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const repertoriosQuery = query(
      collection(firestore, 'repertorios'),
      orderBy('criadoEm', 'desc')
    );

    const unsubscribe = onSnapshot(repertoriosQuery, (querySnapshot) => {
      const data = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
      }));
      setRepertorios(data);
      setLoading(false);
    }, (error) => {
      console.log('Erro ao buscar repertórios:', error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  // quando a tela de repertórios for aberta, limpa o contador local e remoto
  useFocusEffect(
    React.useCallback(() => {
      let mounted = true;
      const limparFlags = async () => {
        try {
          await AsyncStorage.removeItem('nova_repertorio');
          await Notifications.setBadgeCountAsync(0);
        } catch (e) {
          console.log('Erro limpando flag local repertorio', e);
        }
        try {
          const metaRef = doc(firestore, 'meta', 'repertorios');
          await setDoc(metaRef, { newCount: 0, lastClearedAt: new Date(), lastClearedBy: auth.currentUser?.uid || null }, { merge: true });
        } catch (e) {
          console.log('Erro limpando contador remoto meta/repertorios', e);
        }
      };
      limparFlags();
      return () => { mounted = false; };
    }, [])
  );

  const excluirRepertorio = async (id: string) => {
    if (!uidAtual || !UIDS_PERMITIDOS.includes(uidAtual)) return;
    try {
      await auth.currentUser?.getIdToken(true);
      await deleteDoc(doc(firestore, 'repertorios', id));
      setRepertorios(prev => prev.filter(rep => rep.id !== id));
    } catch (error: any) {
      console.log('Erro ao excluir repertório:', error);
    }
  };

  const renderItem = ({ item }: { item: any }) => (
    <NeumorphicContainer style={styles.item}>
      <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center' }}>
        <TouchableOpacity
          onPress={() => navigation.navigate('DetalheRepertorio', { repertorio: item })}
          style={{ flex: 1 }}
        >
          <Text style={styles.itemTitle}>{item.titulo || 'Sem título'}</Text>
          <View style={styles.itemInfoRow}>
            <View style={styles.infoBadge}>
              <Text style={styles.infoBadgeText}>Data</Text>
              <Text style={styles.infoBadgeValue}>{item.data || '-'}</Text>
            </View>
            <View style={styles.infoBadge}>
              <Text style={styles.infoBadgeText}>Responsável</Text>
              <Text style={styles.infoBadgeValue}>{item.responsavel || '-'}</Text>
            </View>
            <View style={styles.infoBadge}>
              <Text style={styles.infoBadgeText}>Músicas</Text>
              <Text style={styles.infoBadgeValue}>{item.musicas ? item.musicas.length : 0}</Text>
            </View>
          </View>
        </TouchableOpacity>
        {uidAtual && UIDS_PERMITIDOS.includes(uidAtual) && (
          <TouchableOpacity
             style={[styles.botaoExcluir, { alignSelf: 'flex-end' }]}
            onPress={() => excluirRepertorio(item.id)}
          >
            <Text style={styles.textoBotao}>🗑️</Text>
          </TouchableOpacity>
        )}
      </View>
    </NeumorphicContainer>
  );

  // Responsivo: pega largura da tela
  const screenWidth = Dimensions.get('window').width;

  return (
    <View style={styles.bg}>
      {/* TOPO FIXO COM BOTÕES E TÍTULO */}
      <View style={[styles.topBar, { width: '100%' }]}>
        <View style={[styles.iconsRow, { width: '100%' }]}>
          <NeumorphicButton
            style={[styles.topButton, { position: 'absolute', left: 0 }]}
            onPress={() => navigation.navigate('Inicio')}
          >
            <Text style={styles.topButtonText}>🏠</Text>
          </NeumorphicButton>
          <NeumorphicButton
            style={[styles.topButton, { position: 'absolute', right: 0 }]}
            onPress={() => navigation.goBack()}
          >
            <Text style={styles.topButtonText}>🔙</Text>
          </NeumorphicButton>
        </View>
        <View style={styles.topTitleContainer}>
          <Text style={styles.topTitle}>🎼 Repertórios</Text>
        </View>
      </View>
      <View style={styles.container}>
        {uidAtual && UIDS_PERMITIDOS.includes(uidAtual) && (
          <NeumorphicButton style={styles.addButton} onPress={() => navigation.navigate('AdicionarRepertorio')}>
            <Text style={styles.addButtonText}>➕ Novo Repertório</Text>
          </NeumorphicButton>
        )}
        {loading ? (
          <ActivityIndicator size="large" color="#ff9800" style={{ marginTop: 40 }} />
        ) : (
          <FlatList
            data={repertorios}
            keyExtractor={item => item.id}
            renderItem={renderItem}
            contentContainerStyle={styles.list}
            ListEmptyComponent={<Text style={styles.emptyText}>Nenhum repertório encontrado.</Text>}
          />
        )}
      </View>
    </View>
  );
}

